<?php
declare(strict_types=1);
putenv('MATCH_STATE_CONSENSUS_TEST_LIBRARY=1');
require __DIR__.'/../scripts/diagnostics/hotel_match_state_country_consensus.php';
function t(bool $ok,string $m):void{if(!$ok){fwrite(STDERR,"FAIL $m\n");exit(1);}}
$core=[1=>'Египет',4=>'Турция',8=>'Мальдивы',9=>'ОАЭ',10=>'Куба',12=>'Шри-Ланка',16=>'Вьетнам',2=>'Таиланд'];$a=msc_country_aliases($core);
t(msc_explicit_countries(['Four Seasons Resort Maldives at Kuda Huraa'],$a)===[8],'maldives marker');t(msc_explicit_countries(['Hotel in Istanbul'],$a)===[],'city not country');t(msc_explicit_countries(['Turkey Maldives'],$a)===[4,8],'multi marker');
$pending=[];for($i=1;$i<=7;$i++)$pending[]=['supplier_namespace'=>'andromeda_catalog','external_hotel_id'=>(string)$i,'evidence_json'=>json_encode(['source'=>['stateKey'=>73,'name'=>'Island '.$i.' Maldives']])];$pending[]=['supplier_namespace'=>'andromeda_catalog','external_hotel_id'=>'9','evidence_json'=>json_encode(['source'=>['stateKey'=>88,'name'=>'One Turkey']])];$inf=msc_marker_consensus($pending,$core);t(isset($inf['73'])&&$inf['73']['country_id']===8&&$inf['73']['winner']===7,'marker consensus');t(!isset($inf['88']),'insufficient vote');$pending2=$pending;$pending2[]=['supplier_namespace'=>'andromeda_catalog','external_hotel_id'=>'10','evidence_json'=>json_encode(['source'=>['stateKey'=>73,'name'=>'Turkey Maldives']])];t(!isset(msc_marker_consensus($pending2,$core)['73']),'multi-country row blocks');
t(msc_countryless_norm('Park Hyatt Maldives Hadahaa',8,$a)==='park hyatt hadahaa','country geography stripped');t(msc_countryless_norm('RIU Palace Maldivas',8,$a)==='riu palace','country synonym stripped');t(msc_countryless_norm('Maldives',8,$a)==='','country-only becomes empty');
$hotels=[1=>['id'=>1,'country_id'=>8,'name'=>'Park Hyatt Hadahaa','region_name'=>null,'subregion_name'=>null,'latitude'=>0.5,'longitude'=>73.0],2=>['id'=>2,'country_id'=>8,'name'=>'Green Beach','region_name'=>null,'subregion_name'=>null,'latitude'=>4.0,'longitude'=>73.0]];$forms=[1=>['Park Hyatt Hadahaa'],2=>['Green Beach']];[$cx,$ct]=msc_countryless_indexes($hotels,$forms,$a);$r=msc_countryless_select(['Park Hyatt Maldives Hadahaa'],8,[['latitude'=>0.5,'longitude'=>73.0]],$hotels,$forms,$a,$cx,$ct);t(($r['route']??'')==='auto_accept_candidate'&&($r['reason']??'')==='unique_exact_after_country_geography_strip'&&($r['target']??0)===1,'country strip exact');$r=msc_countryless_select(['Green Garden Maldives'],8,[],$hotels,$forms,$a,$cx,$ct);t(($r['route']??'')!=='auto_accept_candidate','qualifier preserved after strip');$r=msc_countryless_select(['Green Beach Maldives'],8,[['latitude'=>5.0,'longitude'=>73.0]],$hotels,$forms,$a,$cx,$ct);t(($r['route']??'')==='hard_conflict','gt5km preserved after strip');
t(mcr_norm('The Blue SPA Hotel (EX. Old)')==='blue','shared generic/ex');
